package com.fluxisai.task;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
import java.time.LocalDate; import java.util.*; import com.fluxisai.audit.AuditEventService; import com.fluxisai.common.error.ResourceNotFoundException; import com.fluxisai.common.security.CurrentUser; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.data.domain.*;
@ExtendWith(MockitoExtension.class) class TaskServiceTest { @Mock TaskRepository tasks; @Mock AuditEventService audit; @Mock CurrentUser currentUser; @InjectMocks TaskService service; final UUID user=UUID.randomUUID();
 private void user(){when(currentUser.id()).thenReturn(user);} private TaskRequest request(){return new TaskRequest(" Tarea ","Desc",LocalDate.of(2026,11,20),TaskPriority.HIGH,TaskStatus.IN_PROGRESS,"MANUAL","PROPOSAL",UUID.randomUUID());}
 @Test void createsTaskAndAuditsIt(){user();when(tasks.save(any())).thenAnswer(i->i.getArgument(0));var result=service.create(request());assertEquals("Tarea",result.title());verify(audit).record(eq("TASK"),eq("TASK"),any(),eq("CREATED"),anyString());}
 @Test void trimsTitle(){user();when(tasks.save(any())).thenAnswer(i->i.getArgument(0));assertEquals("Tarea",service.create(request()).title());}
 @Test void keepsDueDate(){user();when(tasks.save(any())).thenAnswer(i->i.getArgument(0));assertEquals(LocalDate.of(2026,11,20),service.create(request()).dueDate());}
 @Test void keepsPriority(){user();when(tasks.save(any())).thenAnswer(i->i.getArgument(0));assertEquals(TaskPriority.HIGH,service.create(request()).priority());}
 @Test void keepsRelatedEntity(){user();when(tasks.save(any())).thenAnswer(i->i.getArgument(0));var result=service.create(request());assertEquals("PROPOSAL",result.relatedEntityType());assertNotNull(result.relatedEntityId());}
 @Test void defaultsStatusAndPriority(){user();when(tasks.save(any())).thenAnswer(i->i.getArgument(0));var result=service.create(new TaskRequest("T",null,null,null,null,null,null,null));assertEquals(TaskStatus.TODO,result.status());assertEquals(TaskPriority.MEDIUM,result.priority());}
 @Test void defaultsOrigin(){user();when(tasks.save(any())).thenAnswer(i->i.getArgument(0));assertEquals("MANUAL",service.create(new TaskRequest("T",null,null,null,null,null,null,null)).origin());}
 @Test void updatesAndAudits(){user();var id=UUID.randomUUID();var task=new Task(user,"Old",null,null,null,null,null,null,null);when(tasks.findByIdAndUserId(id,user)).thenReturn(Optional.of(task));when(tasks.save(any())).thenAnswer(i->i.getArgument(0));var result=service.update(id,request());assertEquals("Tarea",result.title());verify(audit).record(eq("TASK"),eq("TASK"),eq(id),eq("UPDATED"),anyString());}
 @Test void deletesAndAudits(){user();var id=UUID.randomUUID();var task=new Task(user,"T",null,null,null,null,null,null,null);when(tasks.findByIdAndUserId(id,user)).thenReturn(Optional.of(task));service.delete(id);verify(tasks).delete(task);verify(audit).record(eq("TASK"),eq("TASK"),eq(id),eq("DELETED"),anyString());}
 @Test void rejectsUnknownTask(){user();var id=UUID.randomUUID();when(tasks.findByIdAndUserId(id,user)).thenReturn(Optional.empty());assertThrows(ResourceNotFoundException.class,()->service.get(id));}
}
